            "title": "Quantitative chemistry formulae",
            "kind": "formula",
            "items": [
              {
                "term": "Moles from mass",
                "detail": "moles = mass (g) / relative formula mass (Mr). Use to convert a measured mass into an amount for reacting-mass calculations."
              },
              {
                "term": "Mass from moles",
                "detail": "mass (g) = moles x Mr. Use to predict the mass of product or reactant needed."
              },
              {
                "term": "Concentration (mass basis)",
                "detail": "concentration (g/dm3) = mass of solute (g) / volume of solution (dm3). Use for making up solutions of known strength."
              },
              {
                "term": "Concentration (moles basis)",
                "detail": "concentration (mol/dm3) = moles of solute / volume of solution (dm3). Use for titration and reacting-volume calculations."
              },
              {
                "term": "Converting cm3 to dm3",
                "detail": "divide cm3 by 1000 to get dm3. Always convert before using concentration in mol/dm3."
              },
              {
                "term": "Titration moles calculation",
                "detail": "moles = concentration (mol/dm3) x volume (dm3). Find moles of the known solution first, use the balanced equation mole ratio to find moles of the unknown, then convert to concentration or mass as needed."
              },
              {
                "term": "Percentage yield",
                "detail": "percentage yield = (actual mass of product / theoretical maximum mass of product) x 100. Always less than 100 percent due to incomplete reactions, losses during transfer/filtration, or side reactions."
              },
              {
                "term": "Atom economy",
                "detail": "atom economy = (Mr of desired product / sum of Mr of all reactants) x 100. High atom economy means less waste and is important for sustainable industrial processes."
              },
              {
                "term": "Molar gas volume (RTP)",
                "detail": "1 mole of any gas occupies 24 dm3 (24,000 cm3) at room temperature and pressure (20 degC, 1 atm)."
              },
              {
                "term": "Moles of gas from volume",
                "detail": "moles = volume of gas (dm3) / 24. Use for gas volume calculations at RTP, e.g. finding gas produced in a reaction."
              },
              {
                "term": "Limiting reactant identification",
                "detail": "Convert all reactant masses to moles, divide each by its balancing number in the equation; the smallest result identifies the limiting reactant."
              },
              {
                "term": "Relative formula mass (Mr)",
                "detail": "Sum of the relative atomic masses of all atoms shown in the formula, e.g. Mr of CaCO3 = 40 + 12 + (16x3) = 100."
              },
              {
                "term": "Conservation of mass check",
                "detail": "In a closed system, total mass of reactants = total mass of products; an apparent mass change in an open system usually means a gas has entered or escaped."
              }
            ]
